 18	        String title,
 19	        long reservationId,
 20	        String guestName,
 21	        String guestCpf,
 22	        String companyCnpj,
 23	        String companyName,
 24	        String guestPassport,
 25	        String guestCountry,
 26	        int roomNumber,
 27	        RoomType roomType,
 28	        LocalDate checkIn,
 29	        LocalDate checkOut,
 30	        int nights,
 31	        BigDecimal subtotal,
 32	        BigDecimal discount,
 33	        BigDecimal total,
 34	        String text) {
 35	
 36	    private static final BigDecimal WITHHELD_ISS_RATE = new BigDecimal("0.05");
 37	
 38	    public ReservationReceipt(Reservation reservation, Room room) {
 39	        this(reservation, room, reservation.guest());
 40	    }
 41	
 42	    private ReservationReceipt(Reservation reservation, Room room, Guest guest) {
 43	        this(
 44	                titleFor(guest.identification()),
 45	                reservation.id(),
 46	                guest.name(),
 47	                guest.cpf(),
 48	                guest.companyCnpj(),
 49	                guest.companyName(),
 50	                guest.passport(),
 51	                guest.country(),
 52	                room.number(),
 53	                room.type(),
 54	                reservation.checkIn(),
 55	                reservation.checkOut(),
 56	                reservation.price().nights(),
 57	                reservation.price().subtotal(),
 58	                reservation.price().discount(),
 59	                reservation.price().total(),
 60	                null);
 61	    }
 62	
 63	    /** Fills in the text, which is derived from the other fields. */
 64	    public ReservationReceipt {
 65	        if (text == null) {
 66	            text = render(title, reservationId, guestName, guestCpf, companyCnpj, companyName, guestPassport,
 67	                    guestCountry, roomNumber, roomType, checkIn, checkOut, nights, subtotal, discount, total);
 68	        }
 69	    }
