 71	    private static String titleFor(Identification identification) {
 72	        return switch (identification) {
 73	            case Identification.Cpf cpf -> "Comprovante de reserva";
 74	            case Identification.Company company -> "Fatura de hospedagem";
 75	            case Identification.Passport passport -> "Booking receipt";
 76	        };
 77	    }
