 79	    private static String render(
 80	            String title, long reservationId, String guestName, String cpf, String cnpj, String companyName,
 81	            String passport, String country, int roomNumber, RoomType roomType, LocalDate checkIn,
 82	            LocalDate checkOut, int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
 83	        StringBuilder text = new StringBuilder();
 84	        if (passport != null) {
 85	            text.append(title).append(" no. ").append(reservationId).append('\n');
