 87	                    .append(" (passport ").append(passport).append(", ").append(country).append(")\n");
 88	            text.append("Room: ").append(roomNumber).append(" (").append(roomType).append(")\n");
 89	            text.append("Check-in: ").append(TextFormat.englishDate(checkIn))
 90	                    .append(" | Check-out: ").append(TextFormat.englishDate(checkOut))
 91	                    .append(" | ").append(nights).append(nights == 1 ? " night" : " nights").append('\n');
 92	            text.append("Nights: ").append(TextFormat.englishMoney(subtotal)).append('\n');
