 98	        }
 99	        text.append(title).append(" nº ").append(reservationId).append('\n');
100	        if (cnpj != null) {
101	            text.append("Empresa: ").append(companyName).append(" (CNPJ ").append(cnpj).append(")\n");
102	            text.append("Hóspede: ").append(guestName).append('\n');
103	        } else {
104	            text.append("Hóspede: ").append(guestName).append(" (CPF ").append(cpf).append(")\n");
105	        }
106	        text.append("Quarto: ").append(roomNumber).append(" (").append(roomType).append(")\n");
107	        text.append("Entrada: ").append(TextFormat.date(checkIn))
108	                .append(" | Saída: ").append(TextFormat.date(checkOut))
